import{_ as d,c as e,o as l,ah as i}from"./chunks/framework.Ch_PcVtW.js";const p=JSON.parse('{"title":"05 JUNON 编辑报告","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/5_JUNON/2_editing_report.md","filePath":"scripts/output/5_JUNON/2_editing_report.md"}'),o={name:"scripts/output/5_JUNON/2_editing_report.md"};function r(a,t,c,n,u,s){return l(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="_05-junon-编辑报告" tabindex="-1">05 JUNON 编辑报告 <a class="header-anchor" href="#_05-junon-编辑报告" aria-label="Permalink to &quot;05 JUNON 编辑报告&quot;">​</a></h1><h2 id="📊-术语与专有名词统一表" tabindex="-1">📊 术语与专有名词统一表 <a class="header-anchor" href="#📊-术语与专有名词统一表" aria-label="Permalink to &quot;📊 术语与专有名词统一表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日语原文</th><th>译者初译</th><th>最终编辑统一译名</th><th>说明</th></tr></thead><tbody><tr><td>ひと皮剥ける</td><td>更进一步</td><td>更进一步</td><td>统一为“突破瓶颈式成长”，避免字面化。</td></tr><tr><td>ありのまま</td><td>做自己/自然状态</td><td>自然状态（做自己）</td><td>统一核心义，避免“毫无修饰”误读。</td></tr><tr><td>レール</td><td>轨道</td><td>轨道/既定路径</td><td>按语境区分“被铺设路径”与“自主开路”。</td></tr><tr><td>ジャンルレス</td><td>无类型限制（Genreless）</td><td>Genreless（无类型限制）</td><td>保留行业表达并首现释义。</td></tr><tr><td>セトリ（セットリスト）</td><td>歌单编排（Setlist）</td><td>歌单编排（Setlist）</td><td>与全书巡演语境保持一致。</td></tr><tr><td>バイブス</td><td>vibe（氛围张力）</td><td>vibe（氛围张力）</td><td>保留口语感，避免抽象空泛。</td></tr><tr><td>WIND BREAKER/ウィンドブレイカー</td><td>《WIND BREAKER/防风少年》</td><td>《WIND BREAKER/防风少年》</td><td>按全书首现并列规范。</td></tr><tr><td>Stay Strong</td><td>《Stay Strong》</td><td>《Stay Strong》</td><td>作品名统一书名号。</td></tr><tr><td>Boom Boom Back</td><td>《Boom Boom Back》</td><td>《Boom Boom Back》</td><td>作品名统一书名号。</td></tr><tr><td>Bye-Good-Bye</td><td>《Bye-Good-Bye》</td><td>《Bye-Good-Bye》</td><td>作品名统一书名号。</td></tr><tr><td>Mainstream</td><td>《Mainstream》</td><td>《Mainstream》</td><td>作品名统一书名号。</td></tr><tr><td>BMSG FES&#39;25</td><td>「BMSG FES&#39;25」/《BMSG FES》混用</td><td>「BMSG FES&#39;25」（首提）/《BMSG FES》（文中简称）</td><td>按语境做可控简称，不改实体指向。</td></tr><tr><td>Dome Tour</td><td>巨蛋巡演</td><td>巨蛋巡演</td><td>统一类型译法。</td></tr><tr><td>World Tour</td><td>世界巡演</td><td>世界巡演</td><td>统一类型译法。</td></tr><tr><td>Hall ツアー</td><td>Hall 巡演</td><td>Hall 巡演</td><td>沿用全书既定策略。</td></tr></tbody></table><h2 id="❓-针对翻译的疑问记录-q-a" tabindex="-1">❓ 针对翻译的疑问记录（Q&amp;A） <a class="header-anchor" href="#❓-针对翻译的疑问记录-q-a" aria-label="Permalink to &quot;❓ 针对翻译的疑问记录（Q&amp;A）&quot;">​</a></h2><ol><li><p>【中段“BMSG FES”相关段落】</p><ul><li>日文原文：<code>『BMSG FES』</code></li><li>译文初稿：<code>《BMSG FES》</code></li><li>编辑修改与求证理由：正文统一活动名呈现时，首处保留 <code>「BMSG FES&#39;25」</code>，后文简称 <code>《BMSG FES》</code>。请译者确认本章是否需全程带年份，或按全书同章策略“首现全称+后文简称”。</li></ul></li><li><p>【“Power Suit”段】</p><ul><li>日文原文：<code>歌って、パワースーツ着るみたいな</code></li><li>译文初稿：<code>动力战甲（Power Suit）</code></li><li>编辑修改与求证理由：保留初译“动力战甲（Power Suit）”以维持人物口语比喻张力。请译者确认是否需统一为更中性“力量战衣/增幅战甲”，避免科幻感过强。</li></ul></li><li><p>【“更进一步”段】</p><ul><li>日文原文：<code>ひと皮剥ける</code></li><li>译文初稿：<code>更进一步</code></li><li>编辑修改与求证理由：已采用“更进一步”并在语义上处理为“突破瓶颈后的变化”。请译者确认是否需在全书统一替换为“突破瓶颈”，以提升术语一致性。</li></ul></li><li><p>【“轨道”隐喻段】</p><ul><li>日文原文：<code>レールを敷いてくれた／レールがなくなった</code></li><li>译文初稿：<code>铺轨道/轨道没了</code></li><li>编辑修改与求证理由：当前保留“轨道”隐喻，符合本章语义递进。请译者确认全书是否统一允许“轨道/路径”并行，还是固定单一译法。</li></ul></li><li><p>【演技段角色状态】</p><ul><li>日文原文：<code>獣みたいにいてくれ</code></li><li>译文初稿：<code>像野兽一样存在在那里</code></li><li>编辑修改与求证理由：编辑稿改为“像野兽一样待在那里”，口语更自然。请译者确认是否需要更强烈语气版本（如“像野兽那样活着”）以贴近日方导演原话强度。</li></ul></li><li><p>【“做自己”段逻辑】</p><ul><li>日文原文：<code>全部試すっていうほうに行く</code></li><li>译文初稿：<code>先全部试一遍</code></li><li>编辑修改与求证理由：已保留为 JUNON 的决策风格关键词。请译者确认在其他章节中，涉及 JUNON 决策语气时是否统一该表达，避免人物策略标签分散。</li></ul></li></ol><h2 id="⚙️-规范技术调整说明" tabindex="-1">⚙️ 规范技术调整说明 <a class="header-anchor" href="#⚙️-规范技术调整说明" aria-label="Permalink to &quot;⚙️ 规范技术调整说明&quot;">​</a></h2><ul><li>全文统一中文全角标点与省略号“……”。</li><li>中文与英文/数字间统一留空格（如“5 年”“World Tour”）。</li><li>作品名统一使用《》；活动名按访谈现场语境保留「」或约定简称。</li><li>口语犹豫、停顿与自我修正轨迹予以保留，避免过度书面化。</li><li>对“日式被动句/长定语”做了拆解，优先改为中文主动表达与短句推进。</li></ul>',7)])])}const _=d(o,[["render",r]]);export{p as __pageData,_ as default};
